  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

:root[data-motion="reduce"] .confirm-dialog {
  animation: none;
}

@media (prefers-reduced-motion: reduce) {
  .confirm-dialog {
    animation: none;
  }
}
